/// The Claude Code mod `init` writes beside the agent skills: a plugin of
/// function hooks in `.claude/skills/moarch-mod/`, which Claude Code loads
/// on its own from a project's skills folder.
///
/// It guards the generated files and the `// moarch:` anchors, tracks the
/// sources build_runner has not caught up with, opens a project dashboard
/// with `/moarch`, and declares a haiku `runner` agent for long-output
/// checks. Claude Code only: every other agent reads AGENTS.md and the
/// skills, which say the same rules in words.
///
/// The files are TypeScript and are not checked by `dart test`. After
/// changing one, generate a project and run `claude plugin validate` and
/// `claude plugin test` on its `.claude/skills/moarch-mod/`.
class ClaudeModTemplates {
  ClaudeModTemplates._();

  /// The folder the mod lives in, project-relative.
  static const dir = '.claude/skills/moarch-mod';

  /// Every file of the mod, in the order `init` writes them.
  static const all = <ClaudeModFile>[
    ClaudeModFile(
      slug: 'claude-mod-manifest',
      path: '$dir/.claude-plugin/plugin.json',
      title: 'Claude Code mod manifest',
      description:
          "The mod's name and description, which Claude Code lists it by.",
      content: _manifest,
    ),
    ClaudeModFile(
      slug: 'claude-mod-hooks',
      path: '$dir/hooks/hooks.json',
      title: 'Claude Code mod hooks list',
      description: 'Points Claude Code at the hooks module.',
      content: _hooks,
    ),
    ClaudeModFile(
      slug: 'claude-mod-register',
      path: '$dir/hooks/register.tsx',
      title: 'Claude Code mod hooks',
      description:
          'The guards, the build_runner tracking and the /moarch pane.',
      content: _register,
    ),
    ClaudeModFile(
      slug: 'claude-mod-rules',
      path: '$dir/hooks/rules.ts',
      title: 'Claude Code mod rules',
      description:
          'What the hooks check: generated files, anchors, the manifest hash.',
      content: _rules,
    ),
    ClaudeModFile(
      slug: 'claude-mod-types',
      path: '$dir/types/index.d.ts',
      title: 'Claude Code mod state types',
      description: 'The values the mod keeps for the session.',
      content: _types,
    ),
    ClaudeModFile(
      slug: 'claude-mod-runner',
      path: '$dir/agents/runner.md',
      title: 'Claude Code runner agent',
      description:
          'A haiku subagent that runs the checks and reports only what failed.',
      content: _runner,
    ),
    ClaudeModFile(
      slug: 'claude-mod-tsconfig',
      path: '$dir/tsconfig.json',
      title: 'Claude Code mod tsconfig',
      description:
          'Type-checks the mod against the types Claude Code lays beside it.',
      content: _tsconfig,
    ),
    ClaudeModFile(
      slug: 'claude-mod-test-rules',
      path: '$dir/tests/rules.test.ts',
      title: 'Claude Code mod rules tests',
      description: "`claude plugin test`'s checks of rules.ts.",
      content: _testRules,
    ),
    ClaudeModFile(
      slug: 'claude-mod-test-guard',
      path: '$dir/tests/guard.test.ts',
      title: 'Claude Code mod guard tests',
      description: "`claude plugin test`'s checks of the guards and tracking.",
      content: _testGuard,
    ),
    ClaudeModFile(
      slug: 'claude-mod-test-dashboard',
      path: '$dir/tests/dashboard.test.tsx',
      title: 'Claude Code mod pane tests',
      description: "`claude plugin test`'s checks of the /moarch pane.",
      content: _testDashboard,
    ),
  ];

  /// The file `ScaffoldContext.hasClaudeMod` looks for.
  static String get markerPath => '$dir/hooks/register.tsx';

  static const _manifest = r'''
{
  "name": "moarch-mod",
  "version": "1.0.0",
  "description": "Claude Code mod for this moarch project: guards generated files and moarch anchors, tracks pending build_runner runs, and opens a project dashboard with /moarch.",
  "author": { "name": "moarch" },
  "types": "./types/index.d.ts"
}
''';

  static const _hooks = r'''
{ "modules": ["./register.tsx"] }
