describe('rules', () => {
  test('hashes as .moarch.yaml does', async () => {
    expect(hashContent('')).toBe('cbf29ce484222325')
    expect(hashContent('hello\r\nworld\n')).toBe('4ff9450a10388969')
    expect(hashContent("part 'user.g.dart';\nclass Café {}\n")).toBe('5c57d3c219f29e74')
  })

