    expect(needsCodegen('lib/user.dart', "part 'user.freezed.dart';\npart 'user.g.dart';")).toBe(true)
    expect(needsCodegen('lib/main.dart', "import 'app.dart';")).toBe(false)
    expect(needsCodegen('lib/user.g.dart', "part of 'user.dart';")).toBe(false)
  })

