    expect(droppedAnchors(before, '  // moarch:routes\n')).toEqual(['// moarch:registrations'])
    expect(droppedAnchors(before, `GoRoute(),\n${before}`)).toEqual([])
  })

  test('reads the manifest', async () => {
    const manifest = parseManifest(
      "version: '9.8.0'\ngenerated_at: 'x'\nstack: []\nfiles:\n  'lib/main.dart': 'cbf29ce484222325'\n",
    )
    expect(manifest.version).toBe('9.8.0')
    expect(manifest.files).toEqual({ 'lib/main.dart': 'cbf29ce484222325' })
  })

  test('reads paths, commands and the stack', async () => {
    expect(relativeTo('C:\\work\\app', 'C:\\work\\app\\lib\\main.dart')).toBe('lib/main.dart')
    expect(relativeTo('/work/app/', '/elsewhere/a.dart')).toBe('/elsewhere/a.dart')
    expect(runsCodegen('fvm dart run build_runner build -d')).toBe(true)
    expect(runsCodegen('fvm flutter test')).toBe(false)
    expect(stackOf('dependencies:\n  flutter_bloc: ^9.0.0\n')).toBe('bloc')
    expect(stackOf('dependencies:\n  flutter_riverpod: ^3.0.0\n')).toBe('riverpod')
  })
})
