import type { On } from 'claude-code'
import { expect, test } from 'claude-code/testing'

const ROOT = '/work/app'
const ROUTER = `${ROOT}/lib/config/router/app_router.dart`
const MODEL = `${ROOT}/lib/features/user/domain/models/user.dart`
const FILES: Record<string, string> = {
  'lib/config/router/app_router.dart': 'routes: [\n  // moarch:routes\n]\n',
  'lib/features/user/domain/models/user.dart': "part 'user.freezed.dart';\n",
}

/** Answers what the engine would, and records the status line in [statuses]. */
function engine(on: On, statuses: (string | undefined)[]): void {
  on('session.root', () => ({ value: ROOT }))
  on('fs.read', ($, e) => {
    const path = Object.keys(FILES).find(name => e.path.replace(/\\/g, '/').endsWith(name))
    if (path === undefined) throw new Error(`ENOENT ${e.path}`)

    return { value: FILES[path]! }
  })
  on('ui.status', ($, e) => {
    statuses.push(e.text)

    return { value: undefined }
  })
  on('ui.toast', () => ({ value: undefined }))
  on('tool.call', () => ({ result: { ok: true } }))
}

test('refuses edits to generated files and removed anchors', async ($, on) => {
  engine(on, [])

  const generated = await $.tool.call({
    tool: 'Edit',
    file_path: `${ROOT}/lib/features/user/domain/models/user.freezed.dart`,
    old_string: 'a',
    new_string: 'b',
  })
  expect(generated.deny).toContain('Edit lib/features/user/domain/models/user.dart instead')

  const anchor = await $.tool.call({ tool: 'Write', file_path: ROUTER, content: 'routes: []\n' })
  expect(anchor.deny).toContain('// moarch:routes')

  const kept = await $.tool.call({
    tool: 'Edit',
    file_path: ROUTER,
    old_string: '  // moarch:routes',
    new_string: '  GoRoute(),\n  // moarch:routes',
  })
  expect(kept.deny).toBeUndefined()
})

test('shows a model edit as pending until build_runner runs', async ($, on) => {
  const statuses: (string | undefined)[] = []
  engine(on, statuses)

  await $.tool.call({ tool: 'Edit', file_path: MODEL, old_string: 'a', new_string: 'b' })
  expect(statuses.at(-1)).toBe('build_runner pending (1)')

  await $.tool.call({ tool: 'Bash', command: 'fvm dart run build_runner build -d' })
  expect(statuses.at(-1)).toBeUndefined()
})
''';

