  on('fs.read', ($, e) => {
    const path = Object.keys(FILES).find(name => e.path.replace(/\\/g, '/').endsWith(name))
    if (path === undefined) throw new Error(`ENOENT ${e.path}`)

    return { value: FILES[path]! }
  })
  on('fs.list', () => ({
    value: [
      { name: 'cart', kind: 'dir', size: 0, mtimeMs: 0, isLink: false },
      { name: 'auth', kind: 'dir', size: 0, mtimeMs: 0, isLink: false },
    ],
  }))
  on('ui.open', () => ({ value: { isPlaced: true } }))
  on('ui.render', ($, e) => {
    const { Box } = $.ui.resolve(e)

    return <Box />
  })

  await $.command.run({
    command: 'moarch',
    args: '',
    origin: { kind: 'composer' },
    presentation: { isFullscreen: false, columns: 120 },
  })

  for (const surface of ['terminal', 'desktop'] as const) {
    const ui = await $.ui.mount({ plugin: 'moarch-mod', surface, component: 'Pane', requestId: 'moarch', props: PANE })
    expect(await ui.find({ type: 'Text', text: 'shop · riverpod · moarch 9.8.0' })).toBeDefined()
    expect(await ui.find({ type: 'Text', text: 'auth, cart' })).toBeDefined()
    expect(await ui.find({ type: 'Text', text: '2 changed' })).toBeDefined()
    expect(await ui.find({ type: 'Text', text: 'edited  lib/config/theme/app_theme.dart' })).toBeDefined()
    expect(await ui.find({ type: 'Text', text: 'deleted lib/config/router/app_router.dart' })).toBeDefined()
    await ui.unmount()
  }
})
''';
}

/// One file of the Claude Code mod.
class ClaudeModFile {
  /// Creates a file entry.
  const ClaudeModFile({
    required this.slug,
    required this.path,
    required this.title,
    required this.description,
    required this.content,
  });

  /// The catalog slug `moarch update` takes.
  final String slug;

  /// Where it lands, project-relative with forward slashes.
  final String path;

  /// What `moarch update --list` calls it.
  final String title;

  /// One line on what it is for.
  final String description;

  /// The file's content.
  final String content;
}
